using MediatR;
using Microsoft.AspNetCore.Builder; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing;
using Vitarish.Clinic.Application.Queries.Patients; using Vitarish.Clinic.Contracts.Errors; using Vitarish.Clinic.Contracts.Responses; using Vitarish.Clinic.Contracts.Routes; using Vitarish.Clinic.Domain.Models; using Vitarish.Modules.Base.Endpoints; using ContractStatsReadDto = Vitarish.Sea.Contracts.Responses.StatsReadDto; using ContractProgressState = Vitarish.Sea.Contracts.Enums.ProgressState;
using ContractEducation = Vitarish.Clinic.Contracts.Enums.Education; using ContractGender = Vitarish.Clinic.Contracts.Enums.Gender; using ContractPatientSortBy = Vitarish.Clinic.Contracts.Enums.PatientSortBy; using DomainEducation = Vitarish.Clinic.Domain.Enums.Education; using DomainGender = Vitarish.Clinic.Domain.Enums.Gender; using DomainPatientSortBy = Vitarish.Clinic.Domain.Enums.PatientSortBy;
namespace Vitarish.Clinic.Api;
public static class ClinicApiEndpointMapping
{
    public static IEndpointRouteBuilder MapClinicApi(this IEndpointRouteBuilder endpoints){ RouteGroupBuilder group=endpoints.MapProtectedModuleGroup(ClinicApiRoutes.Base); _=group.MapModuleGet(ClinicApiRoutes.Health,()=>Results.Ok(),"ClinicGetHealth"); _=group.MapModulePost(ClinicApiRoutes.Patients,ListPatientsAsync,"ClinicListPatients",typeof(PatientViewDto[])); _=group.MapModulePost(ClinicApiRoutes.PatientCount,CountPatientsAsync,"ClinicCountPatients",typeof(int)); _=group.MapModulePost(ClinicApiRoutes.PatientSearch,SearchPatientsAsync,"ClinicSearchPatients",typeof(PatientViewDto[])); return endpoints; }
    private static async Task<IResult> ListPatientsAsync(PatientListRequest request, ISender sender, CancellationToken ct){ if(request.Skip is <0 || request.Take is <0) return Results.BadRequest(new ClinicError(ClinicErrorCode.ValidationFailure,"Skip and take must be non-negative.")); IReadOnlyList<PatientView> patients=await sender.Send(new GetPatientsQuery(request.Search,request.Skip,request.Take,request.Template,ToDomain(request.SortBy),request.Descending),ct); return Results.Ok(patients.Select(ToContract).ToList()); }
    private static async Task<IResult> CountPatientsAsync(PatientCountRequest request, ISender sender, CancellationToken ct){ int count=await sender.Send(new CountPatientsQuery(request.Search,request.Template),ct); return Results.Ok(count); }
    private static async Task<IResult> SearchPatientsAsync(PatientSearchRequest request, ISender sender, CancellationToken ct){ if(request.Skip is <0 || request.Take is <0) return Results.BadRequest(new ClinicError(ClinicErrorCode.ValidationFailure,"Skip and take must be non-negative.")); IReadOnlyList<PatientView> patients=await sender.Send(new GetPatientsQuery(request.Search,request.Skip,request.Take,request.Template,DomainPatientSortBy.Name,false),ct); return Results.Ok(patients.Select(ToContract).ToList()); }
    private static DomainPatientSortBy? ToDomain(ContractPatientSortBy? sortBy)=>sortBy switch{ContractPatientSortBy.Name=>DomainPatientSortBy.Name,ContractPatientSortBy.Template=>DomainPatientSortBy.Template,ContractPatientSortBy.IdentificationCode=>DomainPatientSortBy.IdentificationCode,ContractPatientSortBy.DateOfBirth=>DomainPatientSortBy.DateOfBirth,ContractPatientSortBy.DateOfSurgery=>DomainPatientSortBy.DateOfSurgery,ContractPatientSortBy.CreatedAt=>DomainPatientSortBy.CreatedAt,ContractPatientSortBy.UpdatedAt=>DomainPatientSortBy.UpdatedAt,_=>null};
    private static PatientViewDto ToContract(PatientView p)=>new(){Id=p.Id,TenantId=p.TenantId,Name=p.Name,Description=p.Description,AvatarFileId=p.AvatarFileId,IdentificationCode=p.IdentificationCode,Template=p.Template,CreatedAt=p.CreatedAt,CreatedBy=p.CreatedBy,UpdatedAt=p.UpdatedAt,UpdatedBy=p.UpdatedBy,DeletedAt=p.DeletedAt,DeletedBy=p.DeletedBy,IsDeleted=p.IsDeleted,UserIds=p.UserIds,FirstName=p.FirstName,LastName=p.LastName,DateOfBirth=p.DateOfBirth,DateOfSurgery=p.DateOfSurgery,Gender=(ContractGender)(int)p.Gender,PlaceOfBirth=p.PlaceOfBirth,Address=p.Address,Education=(ContractEducation)(int)p.Education,Occupation=p.Occupation,FatherName=p.FatherName,Height=p.Height,Weight=p.Weight,Email=p.Email,Phone=p.Phone,Referrer=p.Referrer,InsuranceProvider=p.InsuranceProvider,VisitReason=p.VisitReason,Allergies=p.Allergies,CurrentMedications=p.CurrentMedications,ClinicalNotes=p.ClinicalNotes,EmergencyContactName=p.EmergencyContactName,EmergencyContactPhone=p.EmergencyContactPhone,Stats=ToContract(p.Stats)};
    private static ContractStatsReadDto? ToContract(Vitarish.Sea.Domain.Dto.StatsReadDto? s)=>s is null?null:new(){State=s.State is null?null:(ContractProgressState)(int)s.State.Value,Procedures=s.Procedures,Events=s.Events,CommittedEvents=s.CommittedEvents,EventItems=s.EventItems,NewItems=s.NewItems,Unread=s.Unread,LastUpdate=s.LastUpdate};
}
